    ///
    /// **The last sentence of the text block is load-bearing.** A call that
    /// names neither `path` nor `format` still writes a PNG into the
    /// temporary directory and still ends "Written to <path>." byte for byte
    /// as it did before this phase: five proof scripts (phases 1, 2, 3, 4 and
    /// 6) read the path back out of it with `Written to (\S+\.png)\.` and
    /// every PNG comparison this project makes hangs off that one regular
    /// expression. Anything new to say goes BEFORE it.
    ///
    /// **`burn_in_timecode` is a recipe option and never an export override**
    /// (`RecipeOptions`): it changes the picture, so it travels with the
    /// description of the picture. It is here for parity with `export`, and
    /// because a burn-in lives only in rendered pixels — this is the one tool
    /// that can photograph one, so it is the instrument every claim about
    /// phase 7c's layer is made through.
    ///
    /// **`ungraded` and the four scope booleans are View ▸ Show Ungraded's
    /// and View ▸ Scopes' mirror** (spec §11 GR-4, GR-5, GR-10): the switch,
    /// the panel and its slot picks are view state and never reach this tool,
    /// so it is asked here. `ungraded` is a recipe option like
    /// `burn_in_timecode`; `waveform`, `parade`, `vectorscope` and `histogram`
    /// measure the frame just written through the panel's own analyser, once
    /// for all of them, and write each beside the image as
    /// `<path>.<scope>.json` with a sentence each, in that order
    /// (`writeScopes`, in `AgentServer+Scopes.swift`). `vectorscope_zoom`
    /// (1, 2 or 4, spec §11 GR-31) is a slot's zoom cells' mirror: the
    /// vectorscope counted at that zoom. Anything else is refused by name,
    /// and so is the zoom without `vectorscope: true`, both before the render.
    ///
    /// **`sdr_version` is View ▸ Show SDR Version's mirror** (spec §11 HD-7,
    /// HD-14): an HLG project's SDR version, a recipe option like `ungraded`;
    /// a JPEG of an HLG project is drawn so too, and an SDR project's frame is
    /// unchanged by it.
    ///
    /// **`selection` is View ▸ Show Selection's mirror** (spec §11 GR-13): an
    /// adjustment clip's id, a recipe option like `ungraded` — the clip's
    /// qualifier drawn as grey, every layer in front of it left out, black
    /// where the clip is not on the frame. An id naming no adjustment clip of
    /// the edited project is refused, naming `selection`.
    ///
    /// **A cut-out clip waits for its masks** (spec §11 CO-22 (f)): up to
    /// `Exporter.frameCutoutWait` (30 s), then drawn uncut and named, one
    /// sentence per clip just before the last.
    ///
    /// **A graphic that warned or failed is named** (G-8, G3c): one sentence
    /// per report the frame's pin held, before the last. The set is the
    /// DOCUMENT's (`recipeKey`), not the scoped handle's: a nest draws the
    /// package's modules too.
    func renderFrame(_ a: [String: Any]) throws -> String {
        let selection = try selectionArg(a)
        let context = try onMain {
            () throws -> (ReelProject, [UInt32: URL], Ticks, CGSize, GraphicSet?) in
            let document = try self.target(a)
            let t = try self.optionalTimeArg(a, "t", document) ?? document.playhead
            if let selection, !(document.editedProject.snapshot.clip(selection)
                .map(InspectorTab.isAdjustment) ?? false)
            {
                throw ToolError(
                    message: "selection must name an adjustment clip of this project; clip "
                        + "\(selection) is not one.")
            }
            // `editedProject`, not `project` — road map 2's phase 9. With a
            // nest open (`set_scope`) this renders THAT nest at its own
            // frozen canvas, from its own zero, with the outer transform not
            // applied: the same picture the preview panel is showing, which
            // is what makes a scoped edit checkable at all. It is the one
            // place in this file that side of the split is taken; `export`
            // below stays the DOCUMENT's, because an export writes the whole
            // timeline whatever the timeline happens to be showing. With no
            // nest open the two are the same handle and every earlier
            // phase's frame comparison is unaffected.
            return (
                document.editedProject, document.mediaURLs(), max(0, t),
                document.editedProject.snapshot.canvas.size,
                GraphicRegistry.shared.snapshot(for: document.recipeKey)
            )
        }
        let (project, urls, time, canvasSize, graphics) = context
        var maxWidth: Int?
        if let requested = try intArg(a, "max_width") {
            guard requested >= 16, requested <= 8192 else {
                throw ToolError(message: "max_width must be 16…8192 px (got \(requested)).")
            }
            maxWidth = requested
        }
        let burnIn = try boolArg(a, "burn_in_timecode") ?? false
        let ungraded = try boolArg(a, "ungraded") ?? false
        let sdrVersion = try boolArg(a, "sdr_version") ?? false
        var scopes: [ScopeKind] = []
        for kind in ScopeKind.allCases where try boolArg(a, kind.rawValue) ?? false {
            scopes.append(kind)
        }
        let vectorscopeZoom = try vectorscopeZoomArg(a, measured: scopes.contains(.vectorscope))
        // Resolved BEFORE the render, so a mistyped folder is answered in a
        // millisecond rather than after a decode: `exportProject` orders its
        // own two the same way.
        let (url, format) = try frameDestination(a, at: time)
        // View ▸ Show SDR Version's mirror, and a JPEG of an HLG project, draw
        // its SDR version (spec §11 HD-14 (e), (g)); an SDR project's frame is
        // its own SDR version, the recipe unchanged.
        let output = project.snapshot.canvas.output
        let options = RecipeOptions(
            burnInTimecode: burnIn, ungraded: ungraded, selection: selection,
            dynamicRange: sdrVersion ? .sdr : nil
        ).forFrame(format, output: output)
        // Off the main thread by construction — `Exporter.renderFrame` opens
        // asset tracks and decodes, and says so. A PNG or HEIC keeps depth, so
        // `Exporter` reads a frame showing a deep still or a deep VP9 track
        // through the reader (spec §11 PR-9, PR-12); Save Frame passes the same.
        let rendered = Exporter.renderFrameReported(
            project: project, urls: urls, at: time, maxWidth: maxWidth, options: options,
            graphics: graphics, keepsDepth: format.carriesDepth,
            cutoutWait: Exporter.frameCutoutWait)
        guard let image = rendered.image else {
            throw ToolError(
                message: "No frame at \(time). Either the time is past the end of the timeline, "
                    + "the media is missing, or the timeline is empty.")
        }
        do {
            try FrameWriter.writeFrame(image, as: format, to: url)
        } catch {
            // `FrameWriter.WriteError` names the path and the format in every
            // case it has, so the message passes through as it was written.
            throw ToolError(message: error.localizedDescription)
        }
        guard let data = try? Data(contentsOf: url) else {
            throw ToolError(message: "Wrote \(url.path) but could not read it back.")
        }
        var text =
            "Frame at \(time) ticks of a \(Int(canvasSize.width))×\(Int(canvasSize.height)) px "
            + "canvas, rendered at \(image.width)×\(image.height) px"
        if options.burnInTimecode {
            text += ", with the project timecode burnt in"
        }
        if options.ungraded {
            text += ", with every grade removed"
        }
        if let selection {
            text += ", drawn as clip \(selection)'s qualifier selection (white fully graded, "
                + "black untouched)"
        }
        if output == .hlg, options.dynamicRange == .sdr {
            text += ", as the project's SDR version"
        }
        text += "."
        // Said where the caller can see it rather than only in the schema: a
        // frame off a transparent canvas (phase 7b) has just lost its alpha,
        // and a note that arrives with the file is the one that is read.
        if !format.carriesAlpha {
            text += " " + FrameWriter.flattenNote
        }
        for report in rendered.graphics {
            text += " " + Self.graphicSentence(report)
        }
        // A cursor file the frame could not draw (spec §11 CU-37 (c)).
        for sentence in Exporter.cursorSentences(rendered.cursorWarnings) {
            text += " " + sentence
        }
        if !scopes.isEmpty {
            // The scopes read the frame drawn (spec §11 HD-15 (a), (b)): an HLG
            // project's own picture as HLG, its SDR version (and a JPEG) as SDR.
            let signal = ScopeSignal(output: output, dynamicRange: options.dynamicRange)
            text += " " + (try Self.writeScopes(
                scopes, vectorscopeZoom: vectorscopeZoom, signal: signal, of: image, beside: url))
        }
        // A cut-out clip whose masks were not ready within the wait (spec §11 CO-22 (f)); a
        // picture cut by its foreground names its foreground masks (CO-106).
        let foreground = Set(
            (project.snapshot.clips + project.snapshot.nests.flatMap(\.clips))
                .filter { CutoutWants.kind(of: $0) == .foreground }.map(\.id))
        for sentence in Exporter.cutoutSentences(rendered.uncut, foreground: foreground) {
            text += " " + sentence
        }
        text += " Written to \(url.path)."
        return try callResult(
            content: [
                [
                    "type": "image", "data": data.base64EncodedString(),
                    "mimeType": Self.mimeType(format),
                ],
                ["type": "text", "text": text],
            ], isError: false)
    }

    /// One graphic's report as `render_frame` says it: failed at a frame,
    /// did not compile, or warned — each diagnostic with its location.
    static func graphicSentence(_ report: GraphicReport) -> String {
        let said = report.diagnostics.map { $0.located }.joined(separator: "; ")
        guard let frame = report.frame else {
            return "Graphic \"\(report.name)\" does not compile: \(said)."
        }
        let verb = report.failed ? "failed" : "warned"
        return "Graphic \"\(report.name)\" \(verb) at frame \(frame): \(said)."
    }

    /// Where `render_frame` writes and in what container — its `path` and
    /// `format` arguments resolved together, because neither can be read
    /// without the other.
    ///
    /// **No `path` is the case every proof script takes**, and it is exactly
    /// what it was: a file in the temporary directory named for the tick it
    /// holds, ending in the format's own extension — `.png` unless a caller
    /// asked for something else.
    ///
    /// With a `path`, the format is `FrameWriter`'s answer and not a second
    /// opinion: an explicit `format` wins, else the path's own extension, else
    /// PNG — `export_captions`' rule, one file over. The path then goes
    /// through `destinationURL`, so a wrong extension is REPLACED rather than
    /// appended to: `{path: "shot.jpg", format: "png"}` writes `shot.png`, not
    /// the doubled `shot.jpg.png`, which is why the five image containers
    /// joined `replaceableExtensions` in this phase.
    ///
    /// The folder must already exist and is refused BY NAME when it does not,
    /// which is `export`'s posture at the same point: a tool that created
    /// directories would answer a mistyped path by scattering empty ones.
    private func frameDestination(
        _ a: [String: Any], at time: Ticks
    ) throws -> (url: URL, format: FrameWriter.Format) {
        let requested = try requestedFrameFormat(a)
        guard let given = try stringArg(a, "path") else {
            let format = requested ?? .png
            return (
                Self.temporaryOutput("framejob-frame-\(time)", extension: format.fileExtension),
                format
            )
        }
        let path = try Self.nonEmptyOutputPath(given)
        let format = FrameWriter.format(
            for: URL(fileURLWithPath: (path as NSString).expandingTildeInPath),
            requested: requested)
        let url = try Self.requireFolder(
            of: Self.destinationURL(path, extension: format.fileExtension))
        return (url, format)
    }

    /// The `format` argument, refused BY NAME when it names no container —
    /// nil when it is absent, which is what lets `FrameWriter.format(for:)`
    /// fall back to the path. It is `export_captions`' `requestedFormat` with
    /// three rows instead of two.
    ///
    /// `jpg` is read as `jpeg` on purpose. `FrameWriter.Format`'s raw value is
    /// deliberately NOT its file extension — JPEG has two spellings and
    /// collapsing them would make one of them wrong — and `format(for:)`
    /// already reads both off a path, so refusing four letters here that are
    /// accepted in the argument beside it is an inconsistency a caller meets
    /// on its first try. The schema still advertises the three canonical
    /// names, which is what a caller reading the catalog will send.
    private func requestedFrameFormat(_ a: [String: Any]) throws -> FrameWriter.Format? {
        guard let name = try stringArg(a, "format") else { return nil }
        let lowered = name.lowercased()
        guard let format = FrameWriter.Format(rawValue: lowered == "jpg" ? "jpeg" : lowered)
        else {
            let known = FrameWriter.Format.allCases.map { $0.rawValue }
            throw ToolError(
                message: "format must be one of " + known.joined(separator: ", ")
                    + " (got \"\(name)\").")
        }
        return format
    }

    /// The image block's `mimeType`, read off the format's own `UTType`
    /// rather than switched over a second time here: the block and the file
    /// are then one decision, and a fourth container would arrive described
    /// correctly without anybody remembering this line.
    ///
    /// All three carry one (measured: `image/png`, `image/jpeg`,
    /// `image/heic`). The fallback exists only because the API is optional,
    /// and it is deliberately generic rather than a guess: telling a client
    /// that a HEIC is a PNG is worse than telling it nothing.
    private static func mimeType(_ format: FrameWriter.Format) -> String {
        format.contentType.preferredMIMEType ?? "application/octet-stream"
    }
}
import AppKit

/// `render_frame`'s scope writers: `writeScopes` measures the frame the tool
/// just wrote through the panel's own analyser, once for every kind asked,
/// and writes each kind's counts beside the image, so the panel and the tool
/// cannot count differently (spec §11 GR-5, GR-10).
///
/// A pure move out of `AgentServer+Render.swift` in grading-2's G2-0 (then
/// `writeWaveform`, whose sentence the waveform's still is byte for byte);
/// G2-1 widened it to the parade, the vectorscope and the histogram,
/// grading-4 T4-1 gave the vectorscope its zoom (spec §11 GR-31), and hdr
/// H-4 the frame's signal: an HLG project's frame is measured on BT.2020's
/// constants and said as HLG, its SDR version as an SDR project's (HD-15).
extension AgentServer {

    /// `render_frame {waveform, parade, vectorscope, histogram,
    /// vectorscope_zoom}`: one analyse of `image` for every kind in `kinds`,
    /// the vectorscope at `vectorscopeZoom`, each kind's trace written to
    /// `<path>.<kind>.json`, and one sentence per kind in `ScopeKind.allCases`
    /// order; `signal` is what the frame holds.
    static func writeScopes(
        _ kinds: [ScopeKind], vectorscopeZoom: Int, signal: ScopeSignal, of image: CGImage,
        beside url: URL
    ) throws -> String {
        let asked = Set(kinds)
        let passes = Set(kinds.map { ScopePass($0, zoom: vectorscopeZoom) })
        guard
            let byPass = WaveformAnalyzer.shared?.analyze(
                image: image, passes: passes, signal: signal),
            passes.allSatisfy({ byPass[$0] != nil })
        else {
            let names = ScopeKind.allCases.filter(asked.contains).map(\.rawValue)
            throw ToolError(
                message: "Wrote \(url.path), but its \(names.joined(separator: ", ")) could not "
                    + "be measured: the GPU pass did not run.")
        }
        let traces = WaveformAnalyzer.byKind(byPass)
        var sentences: [String] = []
        for kind in ScopeKind.allCases {
            guard let trace = traces[kind] else { continue }
            let file = URL(fileURLWithPath: url.path + ".\(kind.rawValue).json")
            do {
                let data = try JSONSerialization.data(
                    withJSONObject: trace.json(), options: [.sortedKeys])
                try data.write(to: file)
            } catch {
                throw ToolError(
                    message: "Could not write \(file.path): \(error.localizedDescription)")
            }
            sentences.append(sentence(trace, file: file))
        }
        return sentences.joined(separator: " ")
    }

    /// The sentence `render_frame` says for one kind's trace.
    private static func sentence(_ trace: ScopeTrace, file: URL) -> String {
        if trace.signal == .hlg { return hlgSentence(trace, file: file) }
        func spelled(_ percent: Double) -> String { String(format: "%.1f", percent) }
        switch trace {
        case .waveform(let trace):
            return "Waveform: highlights clipped in \(spelled(trace.highlightsPercent)) % of "
                + "pixels, shadows in \(spelled(trace.shadowsPercent)) %; its 256 × 256 counts "
                + "are in \(file.path)."
        case .parade(let trace):
            let channels = (0..<3).map { trace.channel($0) }.map {
                (spelled($0.highlightsPercent), spelled($0.shadowsPercent))
            }
            return "Parade: red clips high in \(channels[0].0) % of pixels and low in "
                + "\(channels[0].1) %, green in \(channels[1].0) % and \(channels[1].1) %, blue in "
                + "\(channels[2].0) % and \(channels[2].1) %; its 3 × 256 × 256 counts are in "
                + "\(file.path)."
        case .vectorscope(let trace) where trace.zoom > 1:
            return "Vectorscope at ×\(trace.zoom) (Rec. 709 Cb and Cr of the encoded values): "
                + "\(spelled(trace.neutralPercent)) % of pixels are neutral and "
                + "\(spelled(trace.offPlotPercent)) % lie off the plot; its 256 × 256 counts are "
                + "in \(file.path)."
        case .vectorscope(let trace):
            return "Vectorscope (Rec. 709 Cb and Cr of the encoded values): "
                + "\(spelled(trace.neutralPercent)) % of pixels are neutral; its 256 × 256 "
                + "counts are in \(file.path)."
        case .histogram(let trace):
            return "Histogram: highlights clipped in \(spelled(trace.highlightsPercent)) % of "
                + "pixels, shadows in \(spelled(trace.shadowsPercent)) % (by Y′); its R′, G′, B′ "
                + "and Y′ counts per 256 levels are in \(file.path)."
        }
    }

    /// The sentence for an HLG project's trace (spec §11 HD-15 (h)): each
    /// names the signal, the waveform its scale, the vectorscope BT.2020's
    /// matrix and the histogram its weights.
    private static func hlgSentence(_ trace: ScopeTrace, file: URL) -> String {
        func spelled(_ percent: Double) -> String { String(format: "%.1f", percent) }
        switch trace {
        case .waveform(let trace):
            return "Waveform (HLG signal; reference white at 75 %, 203 cd/m², and 100 % at "
                + "1,000 cd/m²): highlights clipped in \(spelled(trace.highlightsPercent)) % of "
                + "pixels, shadows in \(spelled(trace.shadowsPercent)) %; its 256 × 256 counts "
                + "are in \(file.path)."
        case .parade(let trace):
            let channels = (0..<3).map { trace.channel($0) }.map {
                (spelled($0.highlightsPercent), spelled($0.shadowsPercent))
            }
            return "Parade (HLG signal): red clips high in \(channels[0].0) % of pixels and low "
                + "in \(channels[0].1) %, green in \(channels[1].0) % and \(channels[1].1) %, "
                + "blue in \(channels[2].0) % and \(channels[2].1) %; its 3 × 256 × 256 counts "
                + "are in \(file.path)."
        case .vectorscope(let trace) where trace.zoom > 1:
            return "Vectorscope at ×\(trace.zoom) (Rec. 2020 Cb and Cr of the HLG values): "
                + "\(spelled(trace.neutralPercent)) % of pixels are neutral and "
                + "\(spelled(trace.offPlotPercent)) % lie off the plot; its 256 × 256 counts are "
                + "in \(file.path)."
        case .vectorscope(let trace):
            return "Vectorscope (Rec. 2020 Cb and Cr of the HLG values): "
                + "\(spelled(trace.neutralPercent)) % of pixels are neutral; its 256 × 256 "
                + "counts are in \(file.path)."
        case .histogram(let trace):
            return "Histogram (HLG signal): highlights clipped in "
                + "\(spelled(trace.highlightsPercent)) % of pixels, shadows in "
                + "\(spelled(trace.shadowsPercent)) % (by Y′, BT.2020 weights); its R′, G′, B′ "
                + "and Y′ counts per 256 levels are in \(file.path)."
        }
    }
}

    /// of `opsWithoutTools` are skipped for part 2's reason — there is no
    /// tool to declare anything. It costs nothing to run: the tools array is
    /// already parsed and the op list already read.
    static func scopeFailure(_ tools: [[String: Any]], _ ops: Set<String>) -> String? {
        let scopeless =
            tools
            .filter { tool in
                guard let name = tool["name"] as? String, ops.contains(name) else { return false }
                let properties = (tool["inputSchema"] as? [String: Any])?["properties"]
                    as? [String: Any]
                return properties?["scope"] == nil
            }
            .compactMap { $0["name"] as? String }.sorted()
        guard scopeless.isEmpty else {
            return "these op tools do not declare scope: \(scopeless) — every row of spec §6 "
                + "can be sent inside a nest (core/src/scope.rs), and a tool that does not "
                + "say so is one an agent cannot use in there"
        }
        return nil
    }

    // MARK: - set_scope

    /// `set_scope` — double-clicking a nest clip, Clip ▸ Open Nest (⌘↓) and
    /// Clip ▸ Close Nest (⌘↑) (`EditorViewController+NestScope.swift`).
    ///
    /// View state like the playhead, the range and the selection: no op runs,
    /// nothing is undoable and the project is untouched. What it moves is
    /// what `get_project` reports and `render_frame` draws, which is the only
    /// way an agent can SEE what an edit inside a nest did.
    ///
    /// **It is ABSOLUTE**, like the other three `set_` tools: the argument
    /// names where to BE, not a step to take, so `set_scope {clip: 41}` means
    /// the same thing from the timeline and from three levels down. That is
    /// what makes it usable without first reading the current scope back —
    /// and it is why `clip` accepts a nest clip in ANY container, since the
    /// path down to a given id is determined (one id space, and a nest cannot
    /// show itself at any remove).
    func setScope(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let path = try nestScopePath(a, document)
        applyNestScope(path, document)
        var result: [String: Any] = ["ok": true]
        result.merge(scopeReport(document)) { _, new in new }
        result["playhead"] = document.playhead
        result["project"] = summary(document)
        return try jsonResult(result)
    }

    /// `set_scope`'s two arguments read into the path they name.
    ///
    /// `nest` and `clip` are two spellings of one destination and at most one
    /// may be given; neither means the timeline. They are not interchangeable
    /// and the tool says so: `clip` names the nest AND the start the times
    /// inside are measured from, which is what a double-click has and what
    /// two clips showing one nest do not share, while `nest` is the number an
    /// op's own `scope` takes and is the one an agent already has in its
    /// hand.
    private func nestScopePath(_ a: [String: Any], _ document: ProjectDocument) throws
        -> [NestScopeStep]
    {
        let snapshot = document.project.snapshot
        let wantsNest = a["nest"] != nil && !(a["nest"] is NSNull)
        let wantsClip = a["clip"] != nil && !(a["clip"] is NSNull)
        guard !(wantsNest && wantsClip) else {
            throw ToolError(
                message: "Pass nest or clip, not both — they are two spellings of one "
                    + "destination, and clip is the precise one.")
        }
        if wantsClip {
            let id = try idArg(a, "clip")
            guard let path = Self.pathToClip(id, in: snapshot) else {
                throw ToolError(
                    message: "No clip has id \(id), in this timeline or in any of its nests. "
                        + "get_project lists the clips, and each nest's own under nests.")
            }
            guard let clip = NestScope.clips(in: path, of: snapshot)
                .first(where: { $0.id == id }), let nest = clip.source.nestID
            else {
                throw ToolError(
                    message: "Clip \(id) does not show a nest, so there is nothing to open "
                        + "inside it. A nest clip's source.kind is \"nest\".")
            }
            return path + [NestScopeStep(nest: nest, clip: id)]
        }
        if wantsNest {
            let id = try idArg(a, "nest")
            guard snapshot.nest(id) != nil else {
                throw ToolError(
                    message: "no nest with id \(id). get_project lists them under nests.")
            }
            // The earliest TIMELINE clip that shows it, ties to the lower id.
            // A nest shown only from INSIDE another nest is refused rather
            // than guessed at: this is the view, and the app's way in is a
            // clip you can point at. `clip` reaches it, and so does an op's
            // own scope, which needs no view at all.
            guard let entry = snapshot.clips
                .filter({ $0.source.nestID == id })
                .min(by: { ($0.start, $0.id) < ($1.start, $1.id) })
            else {
                throw ToolError(
                    message: "No clip on the timeline shows nest \(id), so the view cannot "
                        + "reach it in one step. Name the nest CLIP instead — set_scope "
                        + "{clip: <id>} works at any depth — or send the op itself with "
                        + "scope: \(id), which needs no view.")
            }
            return [NestScopeStep(nest: id, clip: entry.id)]
        }
        return []
    }

    /// The path from the timeline down to whichever container holds `clip`,
    /// or nil when no container does.
    ///
    /// A breadth-first walk over the containers, with the nests it has
    /// entered remembered: `check_nesting` refuses a cycle, so the visited
    /// set is belt and braces against a hand-written file rather than against
    /// anything the ops can make — but a walk that can be handed a project
    /// from disk does not get to assume the file is sane.
    private static func pathToClip(_ clip: UInt32, in snapshot: ProjectSnapshot)
        -> [NestScopeStep]?
    {
        var queue: [[NestScopeStep]] = [[]]
        var seen: Set<UInt32> = []
        while !queue.isEmpty {
            let path = queue.removeFirst()
            let clips = NestScope.clips(in: path, of: snapshot)
            if clips.contains(where: { $0.id == clip }) { return path }
            for candidate in clips {
                guard let nest = candidate.source.nestID, seen.insert(nest).inserted else {
                    continue
                }
                queue.append(path + [NestScopeStep(nest: nest, clip: candidate.id)])
            }
        }
