    /// Rec. 709 Cb and Cr of an encoded colour, each 0…1 component.
    static func chroma(r: Double, g: Double, b: Double) -> (cb: Double, cr: Double) {
        let luma = 0.2126 * r + 0.7152 * g + 0.0722 * b
        return ((b - luma) / 1.8556, (r - luma) / 1.5748)
    }

